/**
 * Represents a workgroup
 *
 * See ParallelExecutor for more high-level documentation.
 *
 * @author Jonathan Olson <jonathan.olson@colorado.edu>
 */
import '../../../globals.js';
import { alpenglow } from '../alpenglow.js';
export class ParallelWorkgroup {
    constructor(kernel, id, values) {
        this.kernel = kernel;
        this.id = id;
        this.values = values;
        this.workgroupResolves = [];
        this.storageResolves = [];
    }
}
alpenglow.register('ParallelWorkgroup', ParallelWorkgroup);
